const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let bank=[],view='home',filterTopic='All topics',filterKind='All formats',search='',reviewOnly=false,timerId;
let state;try{state=JSON.parse(localStorage.getItem('kernel-v1'))||{}}catch{state={}}state.results||={};state.drafts||={};state.grades||={assignment:100,participation:100,cutoff:90};
const descriptions={'Foundations':'Kernel boundaries & OS design','Processes':'States, fork & program execution','Threads':'Execution contexts & parallelism','IPC':'Communication & shared state','Scheduling':'Gantt charts, metrics & dispatch','Synchronization':'Semaphores, locks & interleavings','Deadlocks':'Resource graphs & safe states','Memory':'Address translation & allocation','Virtual memory':'Replacement, faults & working sets','Storage':'Disk scheduling & flash storage','I/O':'Devices, DMA & data movement','Files':'Inodes, allocation & persistence'};
const icons=['⊞','↳','⋈','⇄','▥','⌘','⊗','▦','▧','▱','⌁','▤'];
function save(){try{localStorage.setItem('kernel-v1',JSON.stringify(state))}catch{toast('Browser storage unavailable. Export a backup.')}}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function result(q){return state.results[q.id]}function mastered(q){let r=result(q);return r&&r.score===q.checks.length&&!r.hint}function go(v){view=v;render();window.scrollTo(0,0)}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#bankCount').textContent=bank.length;({home,practice,lab,mock,progress,sources}[view]||home)()}
const title=(ey,h,sub)=>`<div class="heading"><div><div class="eyebrow">${ey}</div><h1>${h}</h1><p class="sub">${sub}</p></div></div>`;
function home(){let done=bank.filter(q=>result(q)),strong=bank.filter(mastered),due=bank.filter(q=>result(q)&&!mastered(q));$('#app').innerHTML=title('LESS SCROLLING. MORE SOLVING.','Make the final your comeback.','From a 62% midterm to confident, independent problem solving.')+`<section class="darkhero"><div><div class="eyebrow">YOUR NEXT STUDY SESSION</div><h2>Don’t just recognize the answer.<br>Build it from a blank page.</h2><p>Trace the execution. Write the code. Defend the tradeoff. Practice the skills your actual midterm tested.</p><button id="startSession">${due.length?'Revisit a missed problem':'Start a 5-question diagnostic'}</button> <span style="font-size:12px;margin-left:12px;color:#bbceca">Closed notes · ~30 minutes</span></div><div class="terminalart">$ final-prep<br><strong>&gt; think</strong><br><strong>&gt; implement</strong><br><strong>&gt; explain</strong><br>_</div></section><section class="stats"><div class="stat"><label>Practice problems</label><div class="value">${bank.length}</div><small>Worked solutions & marking checklists</small></div><div class="stat"><label>Independent full marks</label><div class="value">${strong.length}<span class="muted" style="font-size:18px"> / ${bank.length}</span></div><small>Self-assessed, without revealing a hint</small></div><div class="stat"><label>Needs another attempt</label><div class="value">${due.length}</div><small>Turn mistakes into your next session</small></div><div class="stat"><label>Final’s effective weight</label><div class="value">75<span style="font-size:19px">%</span></div><small>If final exceeds your 62% midterm</small></div></section><div class="sectiontitle"><h2>Your operating systems map</h2><span>12 areas · all supplied lecture units</span></div><div class="topics">${Object.entries(descriptions).map(([t,d],i)=>{let qs=bank.filter(q=>q.topic===t),n=qs.filter(mastered).length;return `<button class="topiccard" data-topic="${t}"><span class="topicicon">${icons[i]}</span><h3>${t}</h3><p>${d}</p><div class="topicfoot"><span>${qs.length} problems</span><span>${n}/${qs.length} independent</span></div><div class="bar"><i style="width:${n/qs.length*100}%"></i></div></button>`}).join('')}</div><div class="sectiontitle"><h2>A better study loop</h2><span>Practice → explain → retry</span></div><div class="twocol"><div class="panel"><div class="step"><strong>1. Diagnose before reviewing</strong><p>Attempt five mixed problems without notes. Record partial credit honestly.</p></div><div class="step"><strong>2. Rebuild your weakest skill</strong><p>Study the worked reasoning, close it, then solve again from scratch the following day.</p></div><div class="step"><strong>3. Practice under time pressure</strong><p>Use the mixed mock. Show boundaries, units, assumptions and a counterexample when needed.</p></div></div><div class="panel"><span class="badge">YOUR TARGET</span><h3 style="margin-top:16px">A score to work toward</h3><p class="muted">At 100% assignments and participation, a 90% overall target requires 86.67% on the final under the replacement rule.</p><button onclick="go('progress')">Calculate my target</button><p class="source">Editable assumptions. Two completed assignments do not establish the final assignment average. No grade is guaranteed.</p></div></div>`;$('#startSession').onclick=()=>due.length?openQuestion(due[0].id):startMock(true);document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{filterTopic=b.dataset.topic;go('practice')})}
function practice(){let list=bank.filter(q=>(filterTopic==='All topics'||q.topic===filterTopic)&&(filterKind==='All formats'||q.kind===filterKind)&&(!reviewOnly||(result(q)&&!mastered(q)))&&`${q.title} ${q.topic} ${q.prompt}`.toLowerCase().includes(search.toLowerCase()));$('#app').innerHTML=title('WRITE BEFORE YOU REVEAL','The practice bank.','Original drills and adapted exam questions. Solutions open only when you choose.')+`<div class="filters"><input id="search" type="search" aria-label="Search questions" placeholder="Search a skill or concept…" value="${esc(search)}"><select id="topic" aria-label="Topic">${['All topics',...Object.keys(descriptions)].map(t=>`<option ${t===filterTopic?'selected':''}>${t}</option>`).join('')}</select><select id="kind" aria-label="Format">${['All formats','Implement','Trace','Calculate','Explain'].map(t=>`<option ${t===filterKind?'selected':''}>${t}</option>`).join('')}</select><button id="review" class="${reviewOnly?'primary':''}">Mistake review ${reviewOnly?'on':'off'}</button></div><p class="source">${list.length} problems · Checklist scores are self-assessed; written answers are not automatically graded or executed.</p><div class="qlist">${list.map(q=>`<article class="qrow"><div><span class="badge">${q.topic}</span> <small>${q.kind} · ${q.minutes} min ${mastered(q)?'· Independent full marks':result(q)?'· Attempted':''}</small><h3>${esc(q.title)}</h3></div><button data-q="${q.id}">Practice</button></article>`).join('')||'<div class="empty">No matches. Change the filters to explore more skills.</div>'}</div>`;$('#topic').onchange=e=>{filterTopic=e.target.value;practice()};$('#kind').onchange=e=>{filterKind=e.target.value;practice()};$('#search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;practice();$('#search').focus();$('#search').setSelectionRange(pos,pos)};$('#review').onclick=()=>{reviewOnly=!reviewOnly;practice()};document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>openQuestion(+b.dataset.q))}
function openQuestion(id){let q=bank.find(q=>q.id===id),revealed=false;$('#app').innerHTML=`<button id="back">Back to practice</button><div style="margin-top:25px">${title(q.topic+' / '+q.kind,esc(q.title),q.minutes+' minute target · '+q.checks.length+' rubric points')}</div><div class="twocol"><div class="panel"><h3>Your task</h3><p style="white-space:pre-wrap">${esc(q.prompt)}</p><label for="answer"><strong>Your working</strong></label><textarea id="answer" placeholder="State assumptions, show your steps, and explain why it works…">${esc(state.drafts[id]||'')}</textarea><div class="actions"><button id="reveal">Reveal worked solution</button><button id="saveDraft">Save draft</button></div><div id="solution"></div><p class="source">Source: ${esc(q.source)}. Educational practice; not a prediction of your final.</p></div><div class="panel rubric"><span class="eyebrow">SELF-MARKING CHECKLIST</span><h3 style="margin-top:12px">Award evidence, not familiarity.</h3><p class="source">One point per demonstrated criterion. Compare your original answer before editing it.</p>${q.checks.map((c,i)=>`<label><input type="checkbox" name="rubric" value="${i}">${esc(c)}</label>`).join('')}<label for="note">Mistake / next-time rule</label><textarea id="note" style="min-height:100px" placeholder="What will you do differently?">${esc(result(q)?.note||'')}</textarea><button id="record" class="primary">Record attempt</button><p class="source">A perfect score after revealing the solution is recorded as assisted. Retry later without hints.</p></div></div>`;$('#back').onclick=()=>go('practice');$('#answer').oninput=e=>{state.drafts[id]=e.target.value;save()};$('#saveDraft').onclick=()=>{save();toast('Draft saved in this browser')};$('#reveal').onclick=()=>{revealed=true;$('#solution').innerHTML=`<h3>Worked solution</h3><div class="solution">${esc(q.answer)}</div>`;$('#reveal').disabled=true};$('#record').onclick=()=>{if(!$('#answer').value.trim()){toast('Write an attempt before recording it.');return}state.results[id]={score:document.querySelectorAll('[name=rubric]:checked').length,total:q.checks.length,hint:revealed,note:$('#note').value,date:new Date().toISOString()};save();toast('Attempt recorded. Revisit missed criteria tomorrow.');go('progress')}}
function progress(){let done=bank.filter(q=>result(q)),strong=bank.filter(mastered);$('#app').innerHTML=title('MEASURE THE WORK YOU CAN DO','Your progress, honestly.','A checklist is useful evidence. It is not a predicted exam grade.')+`<div class="twocol"><div class="panel"><h2>Coverage & independence</h2><p class="muted">${done.length}/${bank.length} attempted · ${strong.length} full-credit unassisted latest attempts</p>${Object.keys(descriptions).map(t=>{let a=bank.filter(q=>q.topic===t),n=a.filter(mastered).length;return `<div class="step"><strong>${t} <span style="float:right">${n}/${a.length}</span></strong><div class="bar"><i style="width:${100*n/a.length}%"></i></div></div>`}).join('')}<div class="actions"><button id="export">Export progress</button><label class="badge" style="padding:12px">Import backup <input id="import" type="file" accept="application/json" style="max-width:210px"></label></div><p class="source">Keep a backup before switching browsers or clearing site data.</p></div><div><div class="panel"><span class="eyebrow">GRADE TARGET CALCULATOR</span><h2 style="margin-top:12px">What final score do I need?</h2><div class="gradeinputs">${[['assignment','Expected assignment average (%)'],['participation','Expected participation (%)'],['cutoff','Target overall (%)']].map(([k,l])=>`<label>${l}<input type="number" min="0" max="100" step="0.1" id="${k}" value="${state.grades[k]}"></label>`).join('')}</div><div id="gradeResult"></div><p class="source">Overall = 0.20 × assignments + 0.05 × participation + 0.25 × max(62, final) + 0.50 × final. Assumes the syllabus replacement rule applies as written. Target defaults to an illustrative 90%; confirm your course’s A+ boundary. Coursework and final must both be passed.</p></div><div class="panel" style="margin-top:22px"><h3>Your mistake journal</h3>${done.filter(q=>result(q).note).map(q=>`<div class="step"><strong>${esc(q.title)}</strong><p>${esc(result(q).note)}</p></div>`).join('')||'<p class="muted">Record a mistake or next-time rule after a practice problem. It will appear here.</p>'}</div></div></div>`;function calc(){let g=state.grades;if(Object.values(g).some(x=>!Number.isFinite(x)||x<0||x>100)){$('#gradeResult').textContent='Enter percentages from 0 to 100.';return}let rest=.2*g.assignment+.05*g.participation;let f=(g.cutoff-rest-.25*62)/.5;if(f>62)f=(g.cutoff-rest)/.75;f=Math.max(0,f);$('#gradeResult').innerHTML=`<div class="bigresult">${f>100?'Not reachable':f.toFixed(2)+'%'}</div><p class="muted">${f>100?'This target needs more than 100% on the final under these assumptions.':'Minimum final score for this target under the entered assumptions. Aim higher for a margin.'}</p>`;save()}['assignment','participation','cutoff'].forEach(k=>$('#'+k).oninput=e=>{state.grades[k]=e.target.value===''?NaN:+e.target.value;calc()});calc();$('#export').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='kernel-progress.json';a.click();URL.revokeObjectURL(a.href)};$('#import').onchange=async e=>{try{let x=JSON.parse(await e.target.files[0].text());if(!x.results||!x.drafts||!x.grades)throw Error();for(let [id,r]of Object.entries(x.results)){let q=bank.find(q=>q.id===+id);if(!q||!Number.isInteger(r.score)||r.score<0||r.score>q.checks.length||typeof r.note!=='string')throw Error()}state=x;save();progress();toast('Backup imported')}catch{toast('Invalid backup. Current progress kept.')}}}
function simulate(refs,n,policy){let frames=Array(n).fill(null),bits=Array(n).fill(0),dirty=Array(n).fill(false),load=Array(n).fill(0),last=Array(n).fill(0),hand=0,faults=0,writes=0;return refs.map((r,t)=>{let i=frames.indexOf(r.page),fault=i<0,victim=null,write=false;if(fault){faults++;i=frames.indexOf(null);if(i<0){if(policy==='Clock'){while(bits[hand]){bits[hand]=0;hand=(hand+1)%n}i=hand;hand=(hand+1)%n}else if(policy==='OPT'){let distances=frames.map(p=>{let d=refs.slice(t+1).findIndex(x=>x.page===p);return d<0?Infinity:d});i=distances.indexOf(Math.max(...distances))}else{let order=policy==='FIFO'?load:last;i=order.indexOf(Math.min(...order))}victim=frames[i];write=dirty[i];if(write)writes++}frames[i]=r.page;dirty[i]=false;load[i]=t}last[i]=t;bits[i]=1;if(r.write)dirty[i]=true;return {ref:r,frames:[...frames],bits:[...bits],dirty:[...dirty],hand,fault,victim,write,faults,writes}})}
function lab(){ $('#app').innerHTML=title('PREDICT. STEP. CHECK.','The memory workbench.','Check a hand trace against FIFO, LRU, Clock or OPT. Same input, different decisions.')+`<div class="panel"><div class="filters"><label>Reference string<input id="refs" style="display:block;width:100%;margin-top:6px" value="W0 R1 R0 R2 R1 R3" aria-label="Reference string"></label><label>Frames<input id="frames" type="number" min="1" max="12" value="2" style="display:block;width:90px;margin-top:6px"></label><label>Policy<select id="policy" style="display:block;margin-top:6px">${['FIFO','LRU','Clock','OPT'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><p class="source">Space/comma-separated pages, e.g. 1 2 3 or W0 R1 R0. Initially empty; lowest free frame first. Clock hand starts at 0 and moves only during replacement; accesses set the reference bit. OPT ties use the lowest frame.</p><div class="actions"><button id="resetLab" class="primary">Prepare trace</button><button id="stepLab">Next access</button><button id="allLab">Show complete trace</button></div><div id="labstats" class="notice"></div><div id="trace"></div><details><summary>Address translation quick check</summary><div class="filters"><label>Virtual address <input type="number" min="0" id="va" value="5320"></label><label>Page size <input type="number" min="1" id="ps" value="1024"></label><label>Mapped frame <input type="number" min="0" id="fr" value="0"></label><button id="translate">Translate</button></div><p id="translation"></p><p class="source">Assumes the page is valid and resident in the supplied frame. This does not perform a page-table lookup.</p></details></div>`;let rows=[],shown=0;function draw(){$('#trace').innerHTML=rows.slice(0,shown).map((r,i)=>`<div class="labrow"><span>${i+1}. ${r.ref.write?'W':'R'}${r.ref.page}</span><span>${r.fault?'FAULT':'HIT'}</span><span>${r.frames.map((p,j)=>`<span class="frame">${p??'–'}${r.dirty[j]?'*':''}</span>`).join(' ')}</span><span>bits ${r.bits.join(' ')} · hand ${r.hand}</span><span>${r.victim===null?'':`evict ${r.victim}${r.write?' · writeback':''}`}</span></div>`).join('');let r=rows[shown-1];$('#labstats').textContent=`${shown}/${rows.length} accesses · ${r?.faults||0} faults · ${r?.writes||0} dirty writebacks. * marks dirty pages. No end-of-trace flush.`}function reset(){let tokens=$('#refs').value.trim().split(/[\s,]+/),n=+$('#frames').value;if(!Number.isInteger(n)||n<1||n>12||tokens.length>100||tokens.some(x=>!/^([RW])?\d+$/i.test(x)||!Number.isSafeInteger(+x.replace(/^[RW]/i,'')))){toast('Use 1–12 frames and up to 100 nonnegative integer references.');return false}rows=simulate(tokens.map(x=>({page:+x.replace(/^[RW]/i,''),write:/^W/i.test(x)})),n,$('#policy').value);shown=0;draw();return true}$('#resetLab').onclick=reset;$('#stepLab').onclick=()=>{shown=Math.min(shown+1,rows.length);draw()};$('#allLab').onclick=()=>{if(reset()){shown=rows.length;draw()}};$('#policy').onchange=reset;$('#frames').onchange=reset;$('#refs').oninput=()=>{rows=[];shown=0;$('#trace').innerHTML='';$('#labstats').textContent='Input changed. Prepare the trace to continue.'};$('#translate').onclick=()=>{let a=+$('#va').value,p=+$('#ps').value,f=+$('#fr').value;$('#translation').textContent=[a,p,f].every(Number.isSafeInteger)&&a>=0&&p>0&&f>=0&&Number.isSafeInteger(f*p+a%p)?`Page ${Math.floor(a/p)} · offset ${a%p} · physical address ${f*p+a%p}`:'Enter safe nonnegative integers and a positive page size.'};reset()}
function startMock(diagnostic=false){let ids=diagnostic?[1,3,5,10,12]:[1,2,4,6,7,8,10,11,12,35];state.mock={ids,answers:{},end:Date.now()+(diagnostic?30:90)*60000,submitted:false,diagnostic};save();go('mock')}
function mock(){let m=state.mock;if(!m){$('#app').innerHTML=title('PERFORM UNDER PRESSURE','A rehearsal, not a prediction.','A curated mixed exam with implementation, traces and short explanations.')+`<div class="twocol"><div class="panel"><span class="badge">MIXED MOCK</span><h2 style="margin-top:18px">90 minutes. Ten problems.</h2><p class="muted">Scheduling, synchronization, translation, replacement, deadlocks, storage and files. Practice without notes or a calculator. The timer locks your submitted answers; marking happens afterward.</p><button class="primary" id="begin">Start timed mock</button><p class="source">Duration and topic proportions are practice design choices, not the announced final format. Historical take-home programming is not treated as a current exam blueprint.</p></div><div class="panel"><h3>Before you start</h3><p>Use paper for diagrams, then summarize the result here. Keep assumptions explicit and show intermediate states. No solution is revealed during the timed attempt.</p><button id="diagnostic">Take the 30-minute diagnostic</button></div></div>`;$('#begin').onclick=()=>startMock();$('#diagnostic').onclick=()=>startMock(true);return}let selected=m.ids.map(id=>bank.find(q=>q.id===id));$('#app').innerHTML=title(m.diagnostic?'DIAGNOSTIC':'TIMED MIXED MOCK',m.submitted?'Time to mark your work.':'Think clearly. Show your working.',m.submitted?'Compare each original answer to the checklist. Scores are self-assessed.':'Answers save automatically. The timer continues if you leave this page.')+`<div class="panel"><div class="sectiontitle" style="margin-top:0"><h2>${m.diagnostic?'30-minute diagnostic':'90-minute mock'}</h2><span id="timer" class="timer"></span></div>${m.submitted?'<p class="notice">Submitted answers are locked. Full-credit practice scores still need an independent retry to count toward topic independence.</p>':''}${selected.map((q,i)=>`<section class="mockquestion"><span class="badge">${q.topic} · ${q.kind}</span><h3 style="margin-top:12px">${i+1}. ${esc(q.title)}</h3><p>${esc(q.prompt)}</p><textarea data-mock="${q.id}" ${m.submitted?'readonly':''}>${esc(m.answers[q.id]||'')}</textarea>${m.submitted?`<details><summary>Worked solution & rubric</summary><div class="solution">${esc(q.answer)}</div><div class="rubric">${q.checks.map((c,j)=>`<label><input type="checkbox" data-mark="${q.id}-${j}" ${m.marks?.[q.id+'-'+j]?'checked':''}>${esc(c)}</label>`).join('')}</div><p class="source">${esc(q.source)}</p></details>`:''}</section>`).join('')}<div class="actions">${m.submitted?'<button id="newMock">Start another mock</button><button id="printMock">Print / save this attempt</button>':'<button class="primary" id="submitMock">Submit and self-mark</button>'}</div><div id="mockScore"></div></div>`;document.querySelectorAll('[data-mock]').forEach(t=>t.oninput=()=>{m.answers[t.dataset.mock]=t.value;save()});function tick(){if(view!=='mock'||m.submitted){clearInterval(timerId);if($('#timer'))$('#timer').textContent=m.submitted?'Submitted':'';return}let sec=Math.max(0,Math.ceil((m.end-Date.now())/1000));$('#timer').textContent=`${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;if(!sec){m.submitted=true;save();clearInterval(timerId);mock()}}clearInterval(timerId);if(!m.submitted){$('#submitMock').onclick=()=>{m.submitted=true;save();mock()};tick();if(!m.submitted)timerId=setInterval(tick,1000)}else{$('#timer').textContent='Submitted';$('#newMock').onclick=()=>{if(confirm('Replace the current mock? Export progress first to keep it.')){delete state.mock;save();mock()}};$('#printMock').onclick=()=>window.print();function score(){let points=Object.values(m.marks||{}).filter(Boolean).length,total=selected.reduce((s,q)=>s+q.checks.length,0);$('#mockScore').innerHTML=`<div class="mockscore">Self-assessed: ${points} / ${total}</div><p class="source">Equal weight per checklist item; not an official exam marking scale.</p>`}document.querySelectorAll('[data-mark]').forEach(c=>c.onchange=()=>{m.marks||={};m.marks[c.dataset.mark]=c.checked;save();score()});score()}}
function sources(){ $('#app').innerHTML=title('EVIDENCE & EXPECTATIONS','Built from your material.','Use the current syllabus for weighting. Use historical papers for skill practice.')+`<div class="twocol"><div class="panel"><h2>What informed this lab</h2><div class="step"><strong>Fall 2026 actual midterm & marking scheme</strong><p>Primary difficulty reference: execution traces, SRTF metrics, reader-preference behavior, semaphore dependencies, critical-section reasoning and resource graphs. Relevant drills identify the question number.</p></div><div class="step"><strong>All supplied lecture units</strong><p>OS introduction/structure, processes, IPC, threads, scheduling, synchronization, deadlocks, memory, virtual memory, mass storage, I/O and both file-system units. The practice bank groups them into twelve skill areas.</p></div><div class="step"><strong>Assignments 1, 2 and 3</strong><p>Scheduling event ordering; atomic spinlocks, condition-variable semaphores and work queues; address validation, FIFO/LRU/Clock, dirty pages and simulated costs. These drills develop independent reasoning rather than supply submission-ready assignment projects.</p></div><div class="step"><strong>Winter 2025 practice midterm & TPS sheets</strong><p>Supplementary concept coverage. The current actual midterm supplies the stronger signal for applied difficulty.</p></div><div class="step"><strong>Historical final 2016 · Gabriel Wainer</strong><p>Supplementary fixed-value adaptations: memory allocation, TLB cost, translation, IPC, file records and directory operations. Its take-home programming format is not evidence of Ben Earle’s upcoming final format.</p></div><div class="step"><strong>15_Review · headed COMP 3000, April 2026</strong><p>Useful topic recap, but its April21 date and 35%/47.5% weights conflict with the Fall2026 syllabus. Those logistics are not used here. No separate current Ben Earle final practice paper was found in the two supplied archives.</p></div></div><div><div class="panel"><h3>Scoring assumptions</h3><p>The supplied syllabus gives assignments20%, participation5%, midterm25% and final50%. A higher final replaces the midterm, so the final then contributes75%.</p><p class="muted">Your reported midterm is62%. Two assignment scores of100% are encouraging but do not establish your eventual assignment average or independent exam readiness. Enter expected completed-course averages in the target calculator.</p><p class="source">A+ boundary and final date are not confirmed here. The default90% target is editable. Practice results cannot guarantee an outcome.</p></div><div class="panel" style="margin-top:20px"><h3>Study order</h3><p>1. Mixed diagnostic<br>2. Memory & virtual memory<br>3. Synchronization & deadlocks<br>4. Scheduling & process traces<br>5. Storage, I/O & files<br>6. Foundations, threads & IPC<br>7. Timed mock, then revisit every missed criterion</p><p class="source">Repeat unassisted the next day and again several days later. Before your final, verify current coverage and exam logistics with the instructor.</p></div></div></div>`}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelector('.brand').onclick=e=>{e.preventDefault();go('home')};fetch('questions.json').then(r=>r.json()).then(x=>{bank=x;render()}).catch(()=>{$('#app').textContent='Could not load the practice bank. Reload this page.'});
